<script setup lang="ts">
import { ref, watch } from 'vue'

interface Props {
  propProgress: number
}

const props = defineProps<Props>()

const circumference = 2 * Math.PI * 16 // 半径调整为16

const circleStyle = ref({
  strokeDasharray: `${circumference} ${circumference}`,
  strokeDashoffset: circumference,
})
const progress = ref(props.propProgress)
// watch the progress and update the ref
watch(() => props.propProgress, (val) => {
  progress.value = val
  const offset = circumference - (progress.value / 1) * circumference
  circleStyle.value.strokeDashoffset = offset
})
</script>

<template>
  <div class="progress-container w-9 h-9">
    <svg class="progress-circle" width="36" height="36">
      <!-- 进度条的背景 -->
      <circle
        class="progress-ring__background"
        stroke="rgb(89, 89, 89)"
        stroke-width="2"
        fill="transparent"
        r="16"
        cx="18"
        cy="18"
      />
      <!-- 进度条的前景 -->
      <circle
        class="progress-ring__circle"
        stroke="#00c2f1"
        stroke-width="2"
        fill="transparent"
        r="16"
        cx="18"
        cy="18"
        :style="circleStyle"
      />
    </svg>
    <!-- 进度百分比 -->
    <div class="icon-container text-3">
      {{ (progress * 100).toFixed(0) }}%
    </div>
  </div>
</template>

  <style scoped>
  .progress-container {
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
  }
  .progress-circle {
    transform: rotate(-90deg);
  }
  .progress-ring__background,
  .progress-ring__circle {
    transition: stroke-dashoffset 0.35s;
    transform: rotate(-90deg);
    transform-origin: 50% 50%;
  }
  .icon-container {
    position: absolute;
    display: flex;
    align-items: center;
    justify-content: center;
    width: 100%;
    height: 100%;
  }
  </style>
